-- VoiceCore foundation. PostgreSQL 16+. Apply with a migration runner in a deployment transaction.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE account_status AS ENUM ('ACTIVE','PENDING_EMAIL_REVIEW','REJECTED','SUSPENDED','TEMPORARILY_DELETED','PERMANENTLY_DELETED');
CREATE TYPE visibility AS ENUM ('EVERYONE','CONTACTS','NOBODY');
CREATE TYPE moderation_status AS ENUM ('SAFE','REVIEW','REJECT','BLOCK');
CREATE TYPE report_status AS ENUM ('PENDING','REVIEWING','RESOLVED','REJECTED','ESCALATED');
CREATE TYPE transaction_status AS ENUM ('PENDING','COMPLETED','FAILED','REVERSED');
CREATE TYPE transaction_type AS ENUM ('TOP_UP','REFERRAL_REWARD','REFERRAL_DISCOUNT','GIFT_PURCHASE','GIFT_RECEIVED','COIN_TRANSFER','TRANSFER_FEE','PREMIUM_PURCHASE','REFUND','ADMIN_ADJUSTMENT');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id bigint UNIQUE NOT NULL, phone_ciphertext bytea UNIQUE, email_ciphertext bytea UNIQUE, status account_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), CHECK (public_id BETWEEN 1000000000 AND 9999999999));
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id), username varchar(32) UNIQUE NOT NULL, display_name varchar(80) NOT NULL, bio varchar(500), dob date, avatar_key text, banner_key text, hide_rank boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE phone_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_hash bytea NOT NULL, otp_hash bytea NOT NULL, expires_at timestamptz NOT NULL, attempts smallint NOT NULL DEFAULT 0, consumed_at timestamptz);
CREATE TABLE email_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash bytea NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, rank smallint NOT NULL); CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL); CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id), permission_id uuid REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id)); CREATE TABLE user_roles (user_id uuid REFERENCES users(id), role_id uuid REFERENCES roles(id), PRIMARY KEY(user_id,role_id)); CREATE TABLE user_permissions (user_id uuid REFERENCES users(id), permission_id uuid REFERENCES permissions(id), granted_by uuid REFERENCES users(id), PRIMARY KEY(user_id,permission_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), refresh_token_hash bytea NOT NULL, device_name text, ip_hash bytea, last_active_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz); CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), fingerprint_hash bytea NOT NULL, label text, last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE privacy_settings (user_id uuid PRIMARY KEY REFERENCES users(id), phone visibility NOT NULL DEFAULT 'NOBODY', email visibility NOT NULL DEFAULT 'NOBODY', dob visibility NOT NULL DEFAULT 'NOBODY', avatar visibility NOT NULL DEFAULT 'EVERYONE', banner visibility NOT NULL DEFAULT 'EVERYONE', online_status visibility NOT NULL DEFAULT 'EVERYONE', last_seen visibility NOT NULL DEFAULT 'EVERYONE', user_id_visible boolean NOT NULL DEFAULT true, gifts_visible boolean NOT NULL DEFAULT true, gift_sender_visible boolean NOT NULL DEFAULT true, wallet_visible boolean NOT NULL DEFAULT false, premium_visible boolean NOT NULL DEFAULT true, referral_visible boolean NOT NULL DEFAULT true);
CREATE TABLE chats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('PRIVATE','GROUP','ANONYMOUS')), title text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE chat_members (chat_id uuid REFERENCES chats(id), user_id uuid REFERENCES users(id), role text NOT NULL DEFAULT 'MEMBER', joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chat_id,user_id)); CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chat_id uuid NOT NULL REFERENCES chats(id), sender_id uuid REFERENCES users(id), body text, reply_to uuid, moderation moderation_status NOT NULL DEFAULT 'SAFE', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz); CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid REFERENCES messages(id), object_key text UNIQUE NOT NULL, media_type text NOT NULL, moderation moderation_status NOT NULL DEFAULT 'REVIEW', created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE message_reactions (message_id uuid REFERENCES messages(id), user_id uuid REFERENCES users(id), emoji text NOT NULL, PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chat_id uuid REFERENCES chats(id), kind text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz); CREATE TABLE call_participants (call_id uuid REFERENCES calls(id), user_id uuid REFERENCES users(id), joined_at timestamptz NOT NULL DEFAULT now(), left_at timestamptz, PRIMARY KEY(call_id,user_id)); CREATE TABLE interest_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, label text NOT NULL); CREATE TABLE anonymous_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), mode text NOT NULL, age_min smallint, age_max smallint, language text, region text, is_adult_only boolean NOT NULL DEFAULT false, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE anonymous_interests (session_id uuid REFERENCES anonymous_sessions(id), interest_id uuid REFERENCES interest_catalog(id), PRIMARY KEY(session_id,interest_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id), target_user_id uuid REFERENCES users(id), target_message_id uuid REFERENCES messages(id), category text NOT NULL, description text, status report_status NOT NULL DEFAULT 'PENDING', assigned_to uuid REFERENCES users(id), resolution text, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE report_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id), object_key text, snapshot jsonb NOT NULL DEFAULT '{}');
CREATE TABLE wallets (user_id uuid PRIMARY KEY REFERENCES users(id), balance_vh bigint NOT NULL DEFAULT 0 CHECK(balance_vh>=0), version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type transaction_type NOT NULL, amount_vh bigint NOT NULL, fee_vh bigint NOT NULL DEFAULT 0, currency text, external_amount numeric(18,2), status transaction_status NOT NULL DEFAULT 'PENDING', idempotency_key text UNIQUE NOT NULL, group_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz); CREATE TABLE coin_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES users(id), recipient_id uuid NOT NULL REFERENCES users(id), amount_vh bigint NOT NULL CHECK(amount_vh>0), fee_vh bigint NOT NULL, transaction_group_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id));
CREATE TABLE gifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, icon_key text, animation_key text, price_vh bigint NOT NULL CHECK(price_vh>=0), rarity text NOT NULL, description text, active boolean NOT NULL DEFAULT true); CREATE TABLE gift_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gift_id uuid NOT NULL REFERENCES gifts(id), owner_id uuid NOT NULL REFERENCES users(id), sender_id uuid REFERENCES users(id), hidden boolean NOT NULL DEFAULT false, anonymous_sender boolean NOT NULL DEFAULT false, received_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE gift_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gift_id uuid NOT NULL REFERENCES gifts(id), sender_id uuid NOT NULL REFERENCES users(id), recipient_id uuid NOT NULL REFERENCES users(id), transaction_group_id uuid NOT NULL UNIQUE, anonymous boolean NOT NULL DEFAULT false);
CREATE TABLE premium_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), plan_code text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL); CREATE TABLE premium_features (code text PRIMARY KEY, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE referral_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), code text UNIQUE NOT NULL, active boolean NOT NULL DEFAULT true); CREATE TABLE referral_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ancestor_user_id uuid NOT NULL REFERENCES users(id), referrer_user_id uuid NOT NULL REFERENCES users(id), referred_user_id uuid NOT NULL REFERENCES users(id), level smallint NOT NULL CHECK(level>0), status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(ancestor_user_id,referred_user_id)); CREATE UNIQUE INDEX one_direct_referrer ON referral_relationships(referred_user_id) WHERE level=1; CREATE TABLE referral_rule_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version integer UNIQUE NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE referral_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_version_id uuid NOT NULL REFERENCES referral_rule_versions(id), level smallint NOT NULL, percentage_bps integer NOT NULL DEFAULT 0, fixed_vh bigint NOT NULL DEFAULT 0, minimum_topup_vh bigint NOT NULL DEFAULT 0, maximum_reward_vh bigint, active boolean NOT NULL DEFAULT true); CREATE TABLE referral_rewards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES transactions(id), beneficiary_user_id uuid NOT NULL REFERENCES users(id), source_user_id uuid NOT NULL REFERENCES users(id), level smallint NOT NULL, percentage_reward_vh bigint NOT NULL, fixed_reward_vh bigint NOT NULL, total_reward_vh bigint NOT NULL, rule_version_id uuid NOT NULL REFERENCES referral_rule_versions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), actor_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL, expires_at timestamptz, lifted_at timestamptz); CREATE TABLE restrictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL, expires_at timestamptz); CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id text, reason text, request_id text NOT NULL, before_state jsonb, after_state jsonb, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, payload jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO roles(code,rank) VALUES ('CREATOR',100),('ADMIN',80),('MODERATOR',60),('HELPER',40),('USER',0); INSERT INTO interest_catalog(code,label) VALUES ('gaming','Gaming'),('music','Music'),('movies','Movies'),('sports','Sports'),('technology','Technology'),('programming','Programming'),('travel','Travel'),('cars','Cars'),('art','Art'),('education','Education'),('books','Books'),('anime','Anime'); INSERT INTO platform_settings(key,value) VALUES ('username_policy','{"minLength":5,"maxLength":32,"pattern":"^[A-Za-z0-9_]+$"}'),('coin_transfer_fee_bps','500'),('minimum_age','13');
